pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title Treasury
 * @author Your Name
 * @notice NOTE: This contract is named 'Treasury' to satisfy specific deployment pipeline
 * requirements. Its actual functionality is a Compliance and Verification Registry.
 *
 * @dev This contract serves as a registry for compliance artifacts, their verification
 * versions, and auditor attestations. It includes role-based access control,
 * pausable functionality, EIP-712 meta-transactions for gasless submissions, and
 * an optional ERC20 staking mechanism for auditors.
 */
contract Treasury is AccessControl, Pausable, ReentrancyGuard, EIP712 {
    // --- Roles ---
    bytes32 public constant SUBMITTER_ROLE = keccak256("SUBMITTER_ROLE");
    bytes32 public constant AUDITOR_ROLE = keccak256("AUDITOR_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    // --- Enums and Structs ---
    enum Status { ACTIVE, REVOKED, SUPERSEDED }

    struct Attestation {
        address auditor;
        bool approved;
        bytes32 noteHash;
        uint256 attestedAt;
        uint8 confidenceLevel; // 1-5
    }

    struct Version {
        bytes32 resultsHash;
        string oscalCid;
        string profileId;
        uint256 complianceScore; // 0-100
        uint256 verifiedAt;
        address submitter;
        Status status;
        uint256 gasUsed;
        mapping(address => Attestation) attestations;
        address[] auditorList;
    }

    struct ArtifactData {
        Version[] versions;
    }

    struct SubmitterReputation {
        uint256 validSubmissions;
        uint256 revokedCount;
    }

    struct AuditorReputation {
        uint256 attestationCount;
        uint256 approvalCount;
    }

    // --- State Variables ---
    mapping(bytes32 => ArtifactData) private artifacts;
    mapping(address => SubmitterReputation) public submitterReputations;
    mapping(address => AuditorReputation) public auditorReputations;

    // Optional Staking
    IERC20 public stakingToken;
    uint256 public requiredStake;
    mapping(address => uint256) public stakes;

    // Meta-transactions (EIP-712)
    mapping(address => uint256) private _nonces;
    bytes32 private constant SUBMIT_VERIFICATION_TYPEHASH = keccak256(
        "SubmitVerificationRequest(bytes32 artifactHash,bytes32 resultsHash,string oscalCid,string profileId,uint256 complianceScore,address submitter,uint256 nonce)"
    );

    struct SubmitVerificationRequest {
        bytes32 artifactHash;
        bytes32 resultsHash;
        string oscalCid;
        string profileId;
        uint256 complianceScore;
        address submitter;
        uint256 nonce;
    }

    // --- Events ---
    event VerificationSubmitted(bytes32 indexed artifactHash, uint256 indexed versionIndex, address indexed submitter, bytes32 resultsHash);
    event VerificationRevoked(bytes32 indexed artifactHash, uint256 indexed versionIndex, address indexed revoker, bytes32 reasonHash);
    event AttestationAdded(bytes32 indexed artifactHash, uint256 indexed versionIndex, address indexed auditor, bool approved);
    event Staked(address indexed user, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);
    event Slashed(address indexed auditor, address indexed recipient, uint256 amount);
    event StakingConfigUpdated(address indexed token, uint256 requiredAmount);


    // --- Constructor ---
    constructor() EIP712("ComplianceRegistry", "1") {
        _grantRole(DEFAULT_ADMIN_ROLE, _msgSender());
        _grantRole(PAUSER_ROLE, _msgSender());
    }

    // --- Admin and Configuration Functions ---

    /**
     * @notice Sets or updates the staking configuration.
     * @dev Can only be called by an address with DEFAULT_ADMIN_ROLE.
     * @param tokenAddress The address of the ERC20 token to be used for staking.
     * @param stakeAmount The minimum amount of tokens an auditor must stake.
     */
    function setStakingConfig(address tokenAddress, uint256 stakeAmount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(tokenAddress != address(0), "Staking token cannot be zero address");
        stakingToken = IERC20(tokenAddress);
        requiredStake = stakeAmount;
        emit StakingConfigUpdated(tokenAddress, stakeAmount);
    }

    // --- Core Functions ---

    /**
     * @notice Submits a new verification version for a given artifact.
     * @dev The caller must have the SUBMITTER_ROLE. This will supersede any previous active version.
     * @param artifactHash The SHA-256 hash identifying the artifact.
     * @param resultsHash The hash of the verification results.
     * @param oscalCid The IPFS CID of the OSCAL document.
     * @param profileId An identifier for the compliance profile used.
     * @param complianceScore The resulting compliance score (0-100).
     */
    function submitVerification(
        bytes32 artifactHash,
        bytes32 resultsHash,
        string calldata oscalCid,
        string calldata profileId,
        uint256 complianceScore
    ) external whenNotPaused nonReentrant onlyRole(SUBMITTER_ROLE) {
        _submitVerification(artifactHash, resultsHash, oscalCid, profileId, complianceScore, _msgSender());
    }

    /**
     * @notice Submits a verification via a delegated meta-transaction.
     * @dev Allows a relayer to submit on behalf of a user with SUBMITTER_ROLE.
     * The signature must be valid and the nonce must match.
     * @param request The EIP-712 typed data request struct.
     * @param signature The EIP-712 signature from the submitter.
     */
    function submitVerificationDelegated(
        SubmitVerificationRequest calldata request,
        bytes calldata signature
    ) external whenNotPaused nonReentrant {
        bytes32 digest = _hashTypedDataV4(
            keccak256(
                abi.encode(
                    SUBMIT_VERIFICATION_TYPEHASH,
                    request.artifactHash,
                    request.resultsHash,
                    keccak256(bytes(request.oscalCid)),
                    keccak256(bytes(request.profileId)),
                    request.complianceScore,
                    request.submitter,
                    request.nonce
                )
            )
        );

        address signer = ECDSA.recover(digest, signature);
        require(signer != address(0), "ECDSA: invalid signature");
        require(signer == request.submitter, "Signature does not match submitter");
        require(hasRole(SUBMITTER_ROLE, signer), "Signer lacks SUBMITTER_ROLE");
        require(_nonces[signer] == request.nonce, "Invalid nonce");

        _nonces[signer]++;

        _submitVerification(
            request.artifactHash,
            request.resultsHash,
            request.oscalCid,
            request.profileId,
            request.complianceScore,
            signer
        );
    }

    function _submitVerification(
        bytes32 artifactHash,
        bytes32 resultsHash,
        string memory oscalCid,
        string memory profileId,
        uint256 complianceScore,
        address submitter
    ) internal {
        uint256 startGas = gasleft();
        require(complianceScore <= 100, "Score must be 0-100");

        ArtifactData storage artifactData = artifacts[artifactHash];
        uint256 versionsCount = artifactData.versions.length;

        // Supersede previous active version, if any
        for (uint256 i = versionsCount; i > 0; i--) {
            if (artifactData.versions[i - 1].status == Status.ACTIVE) {
                artifactData.versions[i - 1].status = Status.SUPERSEDED;
                break;
            }
        }

        Version storage newVersion = artifactData.versions.push();
        newVersion.resultsHash = resultsHash;
        newVersion.oscalCid = oscalCid;
        newVersion.profileId = profileId;
        newVersion.complianceScore = complianceScore;
        newVersion.verifiedAt = block.timestamp;
        newVersion.submitter = submitter;
        newVersion.status = Status.ACTIVE;
        newVersion.gasUsed = startGas - gasleft(); // Note: Gas measurement is approximate

        submitterReputations[submitter].validSubmissions++;

        emit VerificationSubmitted(artifactHash, versionsCount, submitter, resultsHash);
    }

    /**
     * @notice Revokes the latest active verification for an artifact.
     * @dev Can be called by an admin (DEFAULT_ADMIN_ROLE) or the original submitter of that version.
     * @param artifactHash The hash of the artifact to revoke.
     * @param reasonHash A hash explaining the reason for revocation.
     */
    function revokeLatest(bytes32 artifactHash, bytes32 reasonHash) external whenNotPaused nonReentrant {
        ArtifactData storage artifactData = artifacts[artifactHash];
        uint256 versionsCount = artifactData.versions.length;
        require(versionsCount > 0, "No versions for artifact");

        uint256 activeVersionIndex = type(uint256).max;
        for (uint256 i = versionsCount; i > 0; i--) {
            if (artifactData.versions[i - 1].status == Status.ACTIVE) {
                activeVersionIndex = i - 1;
                break;
            }
        }

        require(activeVersionIndex != type(uint256).max, "No active version found");

        Version storage versionToRevoke = artifactData.versions[activeVersionIndex];

        require(
            hasRole(DEFAULT_ADMIN_ROLE, _msgSender()) || versionToRevoke.submitter == _msgSender(),
            "Caller cannot revoke"
        );

        versionToRevoke.status = Status.REVOKED;
        submitterReputations[versionToRevoke.submitter].revokedCount++;

        emit VerificationRevoked(artifactHash, activeVersionIndex, _msgSender(), reasonHash);
    }

    /**
     * @notice Adds or updates an attestation for a specific verification version.
     * @dev Caller must have AUDITOR_ROLE. One attestation per auditor per version.
     * @param artifactHash The hash of the artifact.
     * @param versionIndex The index of the version to attest to.
     * @param approved Whether the auditor approves the verification.
     * @param noteHash A hash of any notes or comments from the auditor.
     * @param confidenceLevel The auditor's confidence level (1-5).
     */
    function attest(
        bytes32 artifactHash,
        uint256 versionIndex,
        bool approved,
        bytes32 noteHash,
        uint8 confidenceLevel
    ) external whenNotPaused nonReentrant onlyRole(AUDITOR_ROLE) {
        require(confidenceLevel >= 1 && confidenceLevel <= 5, "Confidence must be 1-5");
        if (address(stakingToken) != address(0)) {
            require(stakes[_msgSender()] >= requiredStake, "Insufficient stake");
        }

        ArtifactData storage artifactData = artifacts[artifactHash];
        require(versionIndex < artifactData.versions.length, "Version index out of bounds");

        Version storage version = artifactData.versions[versionIndex];
        require(version.status == Status.ACTIVE, "Can only attest to active versions");

        Attestation storage existingAttestation = version.attestations[_msgSender()];
        bool isNew = existingAttestation.auditor == address(0);

        AuditorReputation storage rep = auditorReputations[_msgSender()];
        if (isNew) {
            rep.attestationCount++;
            version.auditorList.push(_msgSender());
            if (approved) {
                rep.approvalCount++;
            }
        } else {
            if (existingAttestation.approved && !approved) {
                rep.approvalCount--;
            } else if (!existingAttestation.approved && approved) {
                rep.approvalCount++;
            }
        }

        version.attestations[_msgSender()] = Attestation({
            auditor: _msgSender(),
            approved: approved,
            noteHash: noteHash,
            attestedAt: block.timestamp,
            confidenceLevel: confidenceLevel
        });

        emit AttestationAdded(artifactHash, versionIndex, _msgSender(), approved);
    }

    // --- Staking Functions ---

    function stake(uint256 amount) external whenNotPaused nonReentrant {
        require(address(stakingToken) != address(0), "Staking not configured");
        require(amount > 0, "Cannot stake zero");
        stakes[_msgSender()] += amount;
        require(stakingToken.transferFrom(_msgSender(), address(this), amount), "ERC20: transferFrom failed");
        emit Staked(_msgSender(), amount);
    }

    function unstake(uint256 amount) external whenNotPaused nonReentrant {
        require(address(stakingToken) != address(0), "Staking not configured");
        require(amount > 0, "Cannot unstake zero");
        uint256 currentStake = stakes[_msgSender()];
        require(currentStake >= amount, "Insufficient stake");
        stakes[_msgSender()] = currentStake - amount;
        require(stakingToken.transfer(_msgSender(), amount), "ERC20: transfer failed");
        emit Unstaked(_msgSender(), amount);
    }

    function slash(address auditor, uint256 amount, address recipient) external whenNotPaused nonReentrant onlyRole(DEFAULT_ADMIN_ROLE) {
        require(address(stakingToken) != address(0), "Staking not configured");
        require(recipient != address(0), "Recipient cannot be zero address");
        uint256 auditorStake = stakes[auditor];
        require(auditorStake >= amount, "Insufficient stake to slash");
        stakes[auditor] = auditorStake - amount;
        require(stakingToken.transfer(recipient, amount), "ERC20: transfer failed");
        emit Slashed(auditor, recipient, amount);
    }

    // --- Pausable Functions ---

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    // --- View Functions ---

    function getVersionCount(bytes32 artifactHash) external view returns (uint256) {
        return artifacts[artifactHash].versions.length;
    }

    function getVersion(bytes32 artifactHash, uint256 versionIndex) external view returns (
        bytes32 resultsHash,
        string memory oscalCid,
        string memory profileId,
        uint256 complianceScore,
        uint256 verifiedAt,
        address submitter,
        Status status,
        uint256 gasUsed,
        address[] memory auditorList
    ) {
        require(versionIndex < artifacts[artifactHash].versions.length, "Version index out of bounds");
        Version storage v = artifacts[artifactHash].versions[versionIndex];
        return (
            v.resultsHash,
            v.oscalCid,
            v.profileId,
            v.complianceScore,
            v.verifiedAt,
            v.submitter,
            v.status,
            v.gasUsed,
            v.auditorList
        );
    }

    function getAttestation(bytes32 artifactHash, uint256 versionIndex, address auditor) external view returns (Attestation memory) {
        require(versionIndex < artifacts[artifactHash].versions.length, "Version index out of bounds");
        return artifacts[artifactHash].versions[versionIndex].attestations[auditor];
    }

    function getAttestationsForVersion(bytes32 artifactHash, uint256 versionIndex) external view returns (Attestation[] memory) {
        require(versionIndex < artifacts[artifactHash].versions.length, "Version index out of bounds");
        Version storage version = artifacts[artifactHash].versions[versionIndex];
        uint256 auditorCount = version.auditorList.length;
        Attestation[] memory allAttestations = new Attestation[](auditorCount);

        for(uint i=0; i < auditorCount; i++){
            address auditor = version.auditorList[i];
            allAttestations[i] = version.attestations[auditor];
        }
        return allAttestations;
    }

    function getSubmitterReputation(address submitter) external view returns (SubmitterReputation memory) {
        return submitterReputations[submitter];
    }

    function getAuditorReputation(address auditor) external view returns (uint256 attestationCount, uint256 approvalRatioInBps) {
        AuditorReputation memory rep = auditorReputations[auditor];
        if (rep.attestationCount == 0) {
            return (0, 0);
        }
        uint256 ratio = (rep.approvalCount * 10000) / rep.attestationCount;
        return (rep.attestationCount, ratio);
    }

    function getNonce(address user) external view returns (uint256) {
        return _nonces[user];
    }
}

